// Assemble the Copperline Plumbing & Heating theme (6 Divi 5 pages for a local plumbing company) into one pack. Unlike create-real-estate-pack.ts the pages are NOT
// generated by the pipeline's Claude workers: they are composed by the AI Editor for
// Divi 5 plugin from its section recipes (design language organic-warm + a style kit,
// validated by the real LayoutGate) in the validator repo:
//   php scripts/theme-packs/build.php copperline    -> dist/theme-packs/copperline/<role>.json
// and then run through every downstream gate here (validate, stock photos, design lint,
// mobile stacking, dedupe, SEO, real Divi render, critics, ingest).
//
//   npm run dev            # in another shell (ingest target)
//   set -a && . ./.env.local && set +a && COP_DIR=<dir with the six json files> npx tsx scripts/create-copperline-pack.ts
// Smoke test: THEME_ONLY_ROLES=home.
import { randomUUID } from 'node:crypto';
import { readFileSync } from 'node:fs';
import { eq, inArray } from 'drizzle-orm';
import { db } from '@/db/client';
import { packs, packLayouts, layouts } from '@/db/schema';
import { buildThemeDeps } from '@/pipeline/deps';
import { runThemePack, themePageSlug, type ThemeSpec, type ThemePage } from '@/pipeline/theme';
import type { Brief } from '@/pipeline/compose';

const DIR = process.env.COP_DIR ?? '../Divi 5 Deterministic Validator/dist/theme-packs/copperline';

const BRIEF: Brief = {
  businessType: 'service/agency',
  businessName: 'Copperline Plumbing & Heating',
  tagline: 'Plumbing that gets fixed the first time.',
  audience: 'homeowners and landlords who want a licensed, honest plumber who turns up on time and quotes a flat rate before starting',
  conversionGoal: 'book a plumber',
  primaryCta: 'Book a plumber',
  accentColorHex: '#1C4A94',
  voice: 'direct, reassuring and plain-spoken. Short sentences, concrete facts, no jargon and no plumbing puns.',
  palette: { primary: '#1c4a94', secondary: '#4f5d73', tint: '#f2f5fa', dark: '#13233f', heading: '#13233f', body: '#4f5d73' },
  designNotes: 'Corporate-trust design language: white pages, deep navy text and bands, one calm blue accent, IBM Plex Sans throughout, small corners and plenty of facts, lists and numbers.',
};

const BRAND_FACTS =
  'Copperline Plumbing & Heating, 1450 SE Division Street, Portland, OR 97202. Phone (503) 555-0162. hello@copperlineplumbing.com. ' +
  'Sample copy: names, prices and reviews are examples to replace.';

const ROLES: { role: string; roleLabel: string }[] = [
  { role: 'home', roleLabel: 'Home' },
  { role: 'services', roleLabel: 'Services' },
  { role: 'pricing', roleLabel: 'Pricing' },
  { role: 'areas', roleLabel: 'Service Areas' },
  { role: 'about', roleLabel: 'About' },
  { role: 'contact', roleLabel: 'Contact' },
];

const PAGES: ThemePage[] = ROLES.map((r) => ({
  ...r,
  flow: [],
  precomposed: readFileSync(`${DIR}/${r.role}.json`, 'utf8'),
}));

const SPEC: ThemeSpec = { niche: 'plumbing', style: 'corporate', color: 'blue', brief: BRIEF, brandFacts: BRAND_FACTS, pages: PAGES };

const PACK_SLUG = 'copperline-plumbing-theme';
const PACK_TITLE = 'Copperline: Plumbing & Home Services Theme (6 Pages)';
const PRICE_CENTS = 1200;
const DESCRIPTION =
  'A complete six-page Divi 5 website for a plumbing company, heating contractor or any local home-service business, ' +
  'ready to make your own. Home, Services, Pricing, Service Areas, About and Contact share one calm, credible identity: ' +
  'white pages, deep navy type and bands, a single blue accent and small, square corners. Every section is built from ' +
  'proven, validated recipes and a single design language and style kit, so buttons, accordions, forms and type match on ' +
  'every page, on desktop, tablet and phone. A facts-first hero, a services list, flat-rate pricing with a comparison ' +
  'table, a service-area page, a team page with a founder note, FAQs and a contact form with the company details are all ' +
  'in place. Names, prices, hours and reviews are sample copy: swap in your own and publish. No lorem ipsum, no broken ' +
  'layouts. One simple commercial license, unlimited client sites.';
const PACK_SEO = {
  metaTitle: 'Copperline: Plumbing Theme for Divi 5 (6 Pages) | Divi5Lab',
  metaDescription:
    'A complete six-page Divi 5 website theme for a plumbing or home-service company: Home, Services, Pricing, Service ' +
    'Areas, About and Contact. One trustworthy brand, real copy, flat-rate pricing and booking sections.',
  keywords: [
    'divi 5 plumbing theme', 'plumber website template', 'home services divi template', 'plumbing company divi 5 theme',
    'hvac contractor website template', 'divi 5 multi-page theme',
  ],
};

async function upsertPack(slugs: string[]): Promise<void> {
  const rows = await db
    .select({ id: layouts.id, slug: layouts.slug, previews: layouts.previewImageKeys })
    .from(layouts).where(inArray(layouts.slug, slugs));
  const bySlug = new Map(rows.map((r) => [r.slug, r]));
  const found = slugs.filter((s) => bySlug.has(s));
  if (found.length === 0) { console.error('no Copperline pages found in DB — did ingest run?'); process.exitCode = 1; return; }
  if (found.length < slugs.length) console.warn(`only ${found.length}/${slugs.length} pages present; linking what exists`);

  const cover = bySlug.get(slugs[0])?.previews?.[0] ?? bySlug.get(found[0])!.previews?.[0] ?? null;
  const existing = (await db.select().from(packs).where(eq(packs.slug, PACK_SLUG)).limit(1))[0];
  const common = {
    title: PACK_TITLE, description: DESCRIPTION, kind: 'paid' as const,
    priceCents: PRICE_CENTS, stripePriceId: null, coverImageKey: cover, seo: PACK_SEO, status: 'published' as const,
  };
  let packId: string;
  if (existing) {
    packId = existing.id;
    await db.update(packs).set(common).where(eq(packs.id, packId));
  } else {
    packId = randomUUID();
    await db.insert(packs).values({ id: packId, slug: PACK_SLUG, ...common });
  }

  await db.delete(packLayouts).where(eq(packLayouts.packId, packId));
  await db.insert(packLayouts).values(found.map((s, i) => ({ packId, layoutId: bySlug.get(s)!.id, position: i })));

  console.log(`\nPack ready: /packs/${PACK_SLUG}  (paid, ${found.length} pages, cover=${cover ? 'set' : 'none'})`);
}

async function main() {
  const { deps, close } = await buildThemeDeps({ businessName: BRIEF.businessName, logPrefix: '[theme]', defaultMaxBudgetUsd: 1 });

  // Optional smoke-test knob: THEME_ONLY_ROLES=home,listings limits which pages generate.
  const onlyRoles = (process.env.THEME_ONLY_ROLES ?? '').split(',').map((s) => s.trim()).filter(Boolean);
  const spec: ThemeSpec = onlyRoles.length ? { ...SPEC, pages: SPEC.pages.filter((p) => onlyRoles.includes(p.role)) } : SPEC;

  console.log(`[theme] generating ${spec.pages.length} ${spec.niche} pages for "${BRIEF.businessName}"…`);
  const result = await runThemePack(spec, deps);
  await close();
  console.log('[theme] summary:', { generated: result.generated, ingested: result.ingested, dropped: result.dropped, deduped: result.deduped });

  if (onlyRoles.length) { console.log('[theme] partial run (THEME_ONLY_ROLES set) — skipping pack assembly'); return; }
  const expectedSlugs = SPEC.pages.map((p) => themePageSlug(BRIEF, SPEC, p));
  await upsertPack(expectedSlugs);
}

main().then(() => process.exit(0)).catch((e) => { console.error(e); process.exit(1); });
